#include "nxt_controls.h"
#include "nxt_volume.h"
#include "api.h"
#include "msettings.h"
#include "nxt_playback.h"
#include "seek_scan.h"
#include "toast.h"
#include <stdio.h>
extern void Nxt_screenOff(void);
static const int defaults[16]={NC_NONE,NC_NONE,NC_SEEK_BACK,NC_SEEK_FORWARD,NC_PLAY,NC_MENU,NC_QUEUE,NC_LYRICS,NC_PREV,NC_NEXT,NC_SPECTRUM,NC_FAVORITE,NC_NONE,NC_NONE,NC_EQ,NC_QUICK};
static const char *en[]={"Unassigned","Play / pause","Return to menu","Queue","Lyrics","Previous track","Next track","Spectrum","Favorite","EQ / DSP","Quick options","Seek backward","Seek forward","Volume up","Volume down","Brightness up","Brightness down","Shuffle","Repeat mode","Screen off","Play in background","Stop playback"};
static const char *vi[]={"Không gán","Phát / tạm dừng","Về menu","Hàng đợi","Lời bài hát","Bài trước","Bài tiếp","Phổ âm","Yêu thích","EQ / DSP","Tùy chọn nhanh","Tua lùi","Tua tới","Tăng âm lượng","Giảm âm lượng","Tăng độ sáng","Giảm độ sáng","Trộn bài","Chế độ lặp","Tắt màn hình","Phát nền","Dừng nhạc"};
const char *NxtControl_name(int a){return Nxt_text(en[a],vi[a]);}
void NxtControl_defaults(void){for(int i=0;i<16;i++){nxt.keys[i]=Nxt_keyIds[i];nxt.playing_keys[i]=defaults[i];}}
void NxtControl_migrate(void){for(int i=0;i<16;i++)nxt.playing_keys[i]=NC_NONE;for(int i=0;i<16;i++)for(int j=0;j<16;j++)if(nxt.keys[i]==Nxt_keyIds[j])nxt.playing_keys[j]=defaults[i];}
static bool input(int action,int mode){if(Nxt_displayInputBlocked()||Nxt_isLocked())return false;for(int i=0;i<16;i++)if(nxt.playing_keys[i]==action){int k=Nxt_keyIds[i],mask=NxtPad_directionMask(k);if(mode==2&&PAD_isPressed(mask))return true;if(k==BTN_SELECT){if(mode!=2&&PAD_justReleased(k)&&!Nxt_selectLongUsed())return true;}else if(mode==1?PAD_justRepeated(mask):PAD_justPressed(mask))return true;}return false;}
bool NxtControl_pressed(int a){return input(a,0);}bool NxtControl_repeated(int a){return input(a,1);}bool NxtControl_held(int a){return input(a,2);}
bool NxtControl_aux(void){int vol=NxtControl_repeated(NC_VOLUME_UP)-NxtControl_repeated(NC_VOLUME_DOWN),light=NxtControl_repeated(NC_BRIGHT_UP)-NxtControl_repeated(NC_BRIGHT_DOWN);if(vol)NxtVolume_setPercent(NxtVolume_getPercent()+vol);if(light){int v=GetBrightness()+light;SetBrightness(v<0?0:v>10?10:v);}if(vol||light){char s[80];snprintf(s,sizeof(s),"%s: %d%s",light?Nxt_text("Brightness","Độ sáng"):Nxt_text("Volume","Âm lượng"),light?GetBrightness()*10:NxtVolume_getPercent(),light?"%":"");Toast_show(s,900);return true;}if(NxtControl_pressed(NC_SHUFFLE)){Nxt_setShuffle(!nxt.shuffle);return true;}if(NxtControl_pressed(NC_REPEAT)){Nxt_setRepeat((nxt.repeat_mode+1)%3);return true;}if(NxtControl_pressed(NC_SCREEN_OFF)){Nxt_screenOff();return true;}if(NxtControl_pressed(NC_BACKGROUND)){nxt.background=1;Nxt_save();ModuleCommon_requestQuit();return true;}if(NxtControl_pressed(NC_STOP)){Nxt_stop();return true;}return false;}
bool NxtControl_seek(int back,int forward){SeekScan *scan=SeekScan_shared();if(Player_getState()==PLAYER_STATE_STOPPED){bool was=SeekScan_isScanning(scan);SeekScan_cancel(scan);return was;}bool was=SeekScan_isScanning(scan);int dest;bool seek=SeekScan_update(scan,SDL_GetTicks(),NxtControl_held(NC_SEEK_BACK),NxtControl_held(NC_SEEK_FORWARD),Player_getPosition(),Player_getDuration(),back,forward,&dest);if(seek){Player_seek(dest);ModuleCommon_recordInputTime();}return seek||was||SeekScan_isScanning(scan);}
static ModuleExitReason navigation(DisplayContext *d){int sel=0;for(;;){char labels[17][160];const char *rows[17];for(int i=0;i<16;i++){int j=0;while(j<15&&Nxt_keyIds[j]!=nxt.keys[i])j++;snprintf(labels[i],160,"%s → %s",Nxt_keyNames[j],Nxt_keyNames[i]);rows[i]=labels[i];}rows[16]=Nxt_text("Reset menu controls","Khôi phục nút menu");NxtPick r=Nxt_pick(d,Nxt_text("Menu / keyboard controls","Nút menu / bàn phím"),rows,17,&sel,Nxt_text("A Choose button • B Back","A Chọn nút • B Về"));if(r.action==2||r.action==9)return r.action==9?MODULE_EXIT_QUIT:MODULE_EXIT_TO_MENU;if(r.action==1){if(sel==16){for(int i=0;i<16;i++)nxt.keys[i]=Nxt_keyIds[i];}else{int key=0;NxtPick q=Nxt_pick(d,Nxt_text("Physical button","Nút trên máy"),Nxt_keyNames,16,&key,Nxt_text("A Assign • B Cancel","A Gán • B Hủy"));if(q.action==9)return MODULE_EXIT_QUIT;if(q.action==1){int old=nxt.keys[sel];for(int i=0;i<16;i++)if(nxt.keys[i]==Nxt_keyIds[key])nxt.keys[i]=old;nxt.keys[sel]=Nxt_keyIds[key];}}Nxt_save();}}}
ModuleExitReason NxtControl_settings(DisplayContext *d){int sel=0;for(;;){char labels[19][180];const char *rows[19];for(int i=0;i<16;i++){snprintf(labels[i],180,"%s · %s",Nxt_keyNames[i],NxtControl_name(nxt.playing_keys[i]));rows[i]=labels[i];}rows[16]=Nxt_text("Menu / keyboard mapping","Đổi nút menu / bàn phím");rows[17]=Nxt_text("Reset all controls","Khôi phục tất cả nút mặc định");rows[18]=Nxt_text("Physical SELECT + direction: volume/brightness. Hold: lock.","SELECT + hướng: âm lượng/độ sáng. Giữ SELECT: khóa.");NxtPick r=Nxt_pick(d,Nxt_text("Now Playing controls","Nút trong Đang phát"),rows,19,&sel,Nxt_text("A Assign function • B Back","A Gán chức năng • B Về"));if(r.action==2||r.action==9)return r.action==9?MODULE_EXIT_QUIT:MODULE_EXIT_TO_MENU;if(r.action==1){if(sel==17){NxtControl_defaults();Nxt_save();}else if(sel==16){if(navigation(d)==MODULE_EXIT_QUIT)return MODULE_EXIT_QUIT;}else if(sel<16){const char *actions[NC_COUNT];for(int i=0;i<NC_COUNT;i++)actions[i]=NxtControl_name(i);int chosen=nxt.playing_keys[sel];NxtPick q=Nxt_pick(d,Nxt_keyNames[sel],actions,NC_COUNT,&chosen,Nxt_text("A Assign • B Cancel","A Gán • B Hủy"));if(q.action==9)return MODULE_EXIT_QUIT;if(q.action==1){nxt.playing_keys[sel]=chosen;Nxt_save();}}}}}
